<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Models\Project;
use App\Services\Identity;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class ProjectTest extends TestCase {
 use RefreshDatabase;
 private function team():array{$o=User::factory()->create();$m=User::factory()->create();$a=User::factory()->create();$b=User::factory()->create();$w=Workspace::create(['name'=>'Example','type'=>'business','owner_id'=>$o->id]);$w->members()->attach([$o->id=>['role'=>'owner'],$m->id=>['role'=>'manager'],$a->id=>['role'=>'member'],$b->id=>['role'=>'member']]);return [$w,$o,$m,$a,$b];}
 private function login(User $u,Workspace $w):static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>$w->id])->withoutVite();}
 private function data(array $extra=[]):array{return array_merge(['name'=>'Example project','start_date'=>'2026-11-01','due_date'=>'2026-12-31','currency'=>'USD','budget'=>'100.50'],$extra);}
 private function project(Workspace $w,User $o):Project{$p=new Project($this->data());$p->workspace_id=$w->id;$p->creator_id=$o->id;$p->save();$p->members()->attach($o->id,['role'=>'manager']);return $p->fresh();}
 private function taskData(array $extra=[]):array{return array_merge(['title'=>'Implement feature','priority'=>'medium','start_date'=>'2026-11-27','due_date'=>'2026-12-01','requires_approval'=>0],$extra);}
 private function path(Project $p,string $suffix=''):string{return '/projects/'.$p->id.$suffix;}
 public function test_guest_and_personal_denied():void{$this->get('/projects')->assertRedirect('/login');$u=User::factory()->create();$this->login($u,Identity::personal($u))->get('/projects')->assertForbidden();}
 public function test_templates_and_project_creation():void{[$w,$o,$m,$a]=$this->team();$this->login($o,$w)->post('/projects/templates',['name'=>'Launch','tasks'=>"Design\nBuild"])->assertRedirect();$this->post('/projects',$this->data(['template_id'=>DB::table('project_templates')->value('id')]))->assertRedirect();$p=Project::firstOrFail();$this->assertSame(2,DB::table('project_tasks')->count());$this->get('/projects')->assertOk()->assertSee('Example project');$this->get($this->path($p))->assertOk()->assertSee('Gantt timeline')->assertSee('Build');$this->login($a,$w)->post('/projects',$this->data())->assertForbidden();}
 public function test_project_membership_and_cross_workspace_denial():void{[$w,$o,$m,$a,$b]=$this->team();$p=$this->project($w,$o);$this->login($a,$w)->get($this->path($p))->assertForbidden();$this->get('/projects')->assertOk()->assertDontSee('Example project');$this->login($o,$w)->post($this->path($p,'/members'),['user_id'=>$a->id,'role'=>'member'])->assertRedirect();$this->login($a,$w)->get($this->path($p))->assertOk();$this->post($this->path($p,'/members'),['user_id'=>$b->id,'role'=>'member'])->assertForbidden();[$other,$oo]=$this->team();$this->login($oo,$other)->get($this->path($p))->assertNotFound();}
 public function test_manager_demotion_and_removed_membership():void{[$w,$o,$m,$a]=$this->team();$p=$this->project($w,$o);$p->members()->attach($m->id,['role'=>'manager']);$this->login($m,$w)->post($this->path($p,'/tasks'),$this->taskData())->assertRedirect();$this->login($o,$w)->patch('/workspaces/'.$w->id.'/members/'.$m->id,['role'=>'member'])->assertRedirect();$this->login($m,$w)->post($this->path($p,'/tasks'),$this->taskData())->assertForbidden();$w->members()->detach($m->id);$this->login($m,$w)->get($this->path($p))->assertForbidden();}
 public function test_assignments_versions_and_dependencies():void{[$w,$o,$m,$a,$b]=$this->team();$p=$this->project($w,$o);$p->members()->attach($a->id,['role'=>'member']);$this->login($o,$w)->post($this->path($p,'/tasks'),$this->taskData(['assignee_id'=>$b->id]))->assertStatus(422);$this->post($this->path($p,'/tasks'),$this->taskData(['assignee_id'=>$a->id]))->assertRedirect();$this->post($this->path($p,'/tasks'),$this->taskData(['title'=>'Dependency']))->assertRedirect();[$t,$dep]=DB::table('project_tasks')->orderBy('id')->pluck('id')->all();$this->post($this->path($p,"/tasks/$t/dependencies"),['depends_on_id'=>$dep])->assertRedirect();$this->post($this->path($p,"/tasks/$dep/dependencies"),['depends_on_id'=>$t])->assertSessionHasErrors('depends_on_id');$this->login($a,$w)->patch($this->path($p,"/tasks/$t/status"),['status'=>'completed','version'=>1])->assertSessionHasErrors('status');$this->login($o,$w)->patch($this->path($p,"/tasks/$dep/status"),['status'=>'completed','version'=>1])->assertRedirect();$this->login($a,$w)->patch($this->path($p,"/tasks/$t/status"),['status'=>'completed','version'=>1])->assertRedirect();$this->patch($this->path($p,"/tasks/$t/status"),['status'=>'in_progress','version'=>1])->assertSessionHasErrors('version');}
 public function test_approval_and_milestone_workflow():void{[$w,$o,$m,$a]=$this->team();$p=$this->project($w,$o);$p->members()->attach($a->id,['role'=>'member']);$this->login($o,$w)->post($this->path($p,'/milestones'),['title'=>'Delivery','due_date'=>'2026-12-10'])->assertRedirect();$milestone=DB::table('project_milestones')->value('id');$this->post($this->path($p,'/tasks'),$this->taskData(['assignee_id'=>$a->id,'requires_approval'=>1,'milestone_id'=>$milestone]))->assertRedirect();$t=DB::table('project_tasks')->value('id');$this->patch($this->path($p,"/milestones/$milestone"),[])->assertSessionHasErrors('milestone');$this->login($a,$w)->patch($this->path($p,"/tasks/$t/status"),['status'=>'completed','version'=>1])->assertSessionHasErrors('status');$this->patch($this->path($p,"/tasks/$t/status"),['status'=>'review','version'=>1])->assertRedirect();$id=DB::table('project_approvals')->value('id');$this->patch($this->path($p,"/approvals/$id"),['status'=>'approved'])->assertForbidden();$this->login($o,$w)->patch($this->path($p,"/approvals/$id"),['status'=>'approved'])->assertRedirect();$this->assertDatabaseHas('project_tasks',['id'=>$t,'status'=>'completed']);$this->patch($this->path($p,"/milestones/$milestone"),[])->assertRedirect();}
 public function test_budget_privacy_and_decimal_expenses():void{[$w,$o,$m,$a]=$this->team();$p=$this->project($w,$o);$p->members()->attach($a->id,['role'=>'member']);$this->travelTo(Carbon::parse('2026-11-27 12:00 UTC'));$d=['title'=>'Private expense','amount'=>'19.95','local_date'=>'2026-11-27'];$this->login($o,$w)->post($this->path($p,'/expenses'),$d)->assertRedirect();$this->get($this->path($p))->assertOk()->assertSee('Private expense')->assertSee('19.95');$this->login($a,$w)->get($this->path($p))->assertOk()->assertDontSee('Private expense')->assertDontSee('100.50');$this->post($this->path($p,'/expenses'),$d)->assertForbidden();}
 public function test_time_cap_and_foreign_task():void{[$w,$o,$m,$a]=$this->team();$p=$this->project($w,$o);$other=$this->project($w,$o);$this->travelTo(Carbon::parse('2026-11-27 12:00 UTC'));$this->login($o,$w)->post($this->path($other,'/tasks'),$this->taskData())->assertRedirect();$d=['description'=>'Work','local_date'=>'2026-11-27','minutes'=>1000];$this->post($this->path($p,'/time'),$d+['project_task_id'=>DB::table('project_tasks')->value('id')])->assertNotFound();$this->post($this->path($p,'/time'),$d)->assertRedirect();$this->post($this->path($other,'/time'),$d)->assertSessionHasErrors('minutes');}
 public function test_private_files_and_wrong_parent():void{Storage::fake('local');[$w,$o,$m,$a]=$this->team();$p=$this->project($w,$o);$other=$this->project($w,$o);$this->login($o,$w)->post($this->path($p,'/attachments'),['file'=>UploadedFile::fake()->createWithContent('brief.txt','example')])->assertRedirect();$f=DB::table('project_attachments')->first();$this->get($this->path($p,'/attachments/'.$f->id))->assertOk()->assertDownload('brief.txt');$this->get($this->path($other,'/attachments/'.$f->id))->assertNotFound();$this->login($a,$w)->get($this->path($p,'/attachments/'.$f->id))->assertForbidden();$this->login($o,$w)->delete($this->path($p,'/attachments/'.$f->id))->assertRedirect();Storage::disk('local')->assertMissing($f->path);}
 public function test_archive_comments_dashboard_and_activity():void{[$w,$o,$m,$a]=$this->team();$p=$this->project($w,$o);$this->login($o,$w)->post($this->path($p,'/comments'),['body'=>'<script>alert(1)</script>'])->assertRedirect();$this->get($this->path($p))->assertOk()->assertDontSee('<script>alert(1)</script>',false)->assertSee('project comment created');$this->get('/dashboard')->assertOk()->assertSee('Project management');$this->patch($this->path($p,'/status'),['status'=>'archived'])->assertRedirect();$this->post($this->path($p,'/comments'),['body'=>'Forbidden'])->assertStatus(409);}
}
